38	func fetchGraphStore(ctx context.Context, opts Options, repoDir, binary, profile string) (graphStoreDescriptor, error) {
39		if ctx == nil {
40			ctx = context.Background()
41		}
42		if binary == "" {
43			binary = "entire"
44		}
45		if profile == "" {
46			profile = "full"
47		}
48		args := []string{"graph", "store", "--repo", repoDir, "--profile", profile}
49		ignores, err := semanticProviderIgnoreFiles(repoDir)
50		if err != nil {
51			return graphStoreDescriptor{}, err
52		}
53		for _, ignore := range ignores {
54			args = append(args, "--ignore-file", ignore)
55		}
56		ctx, cancel := context.WithTimeout(ctx, graphTaskContextTimeout)
57		defer cancel()
58		stdout, stderr, err := opts.Runner.Run(ctx, repoDir, binary, args...)
59		if err != nil {
60			detail := strings.ToLower(string(stderr) + string(stdout))
61			if strings.Contains(detail, "unknown command") || strings.Contains(detail, "unknown subcommand") {
62				return graphStoreDescriptor{}, errGraphStoreUnsupported
63			}
64			return graphStoreDescriptor{}, fmt.Errorf("Graph read-only store unavailable: %w: %s", err, firstLine(strings.TrimSpace(string(stderr))))
65		}
66		var d graphStoreDescriptor
67		if err := json.Unmarshal(stdout, &d); err != nil {
68			return d, fmt.Errorf("decode Graph store descriptor: %w", err)
69		}
70		if d.StoreUnavailable {
71			return d, fmt.Errorf("%w: %s; run %s", errGraphStoreUnavailable, d.Detail, brainInvocation(os.LookupEnv, "refresh index"))
72		}
73		if d.ContractVersion != 1 {
74			return d, errGraphStoreUnsupported
75		}
76		if !filepath.IsAbs(d.Path) || d.EntryDigest == "" || d.Commit == "" || d.Tree == "" {
77			return d, errors.New("Graph returned an unsupported or incomplete store descriptor")
78		}
79		return d, nil
80	}
