1003	// parseSemanticSchemaVersion splits a provider schema_version into its major
1004	// and minor numbers. ADR 0001 fixes the shape as major.minor, so anything that
1005	// is not two non-negative integers is not a version this reader can reason
1006	// about: the old implementation only looked at the text before the first dot,
1007	// which silently accepted "1.abc" and "1." as if they were ordinary 1.x minors
1008	// and let a malformed header ride straight into the store.
1009	func parseSemanticSchemaVersion(version string) (int, int, error) {
1010		majorText, rest, ok := strings.Cut(version, ".")
1011		if !ok {
1012			return 0, 0, fmt.Errorf("semantic schema version %q is not major.minor", version)
1013		}
1014		// A trailing patch component is tolerated and ignored: it is additive, and
1015		// refusing it would violate the tolerant-reader rule.
1016		minorText, _, _ := strings.Cut(rest, ".")
1017		major, err := strconv.Atoi(majorText)
1018		if err != nil || major < 0 {
1019			return 0, 0, fmt.Errorf("semantic schema version %q has a non-numeric major", version)
1020		}
1021		minor, err := strconv.Atoi(minorText)
1022		if err != nil || minor < 0 {
1023			return 0, 0, fmt.Errorf("semantic schema version %q has a non-numeric minor", version)
1024		}
1025		return major, minor, nil
1026	}
