1028	// validateSemanticSchema applies ADR 0001's compatibility boundary: refuse an
1029	// unknown major, accept every minor within the supported major.
1030	func validateSemanticSchema(version string) error {
1031		major, _, err := parseSemanticSchemaVersion(version)
1032		if err != nil {
1033			return fmt.Errorf("%w (this build reads %s)", err, semanticSupportedSchemaRange)
1034		}
1035		if strconv.Itoa(major) != semanticSupportedMajor {
1036			return fmt.Errorf("unsupported semantic schema major version %q: this build reads %s", strconv.Itoa(major), semanticSupportedSchemaRange)
1037		}
1038		return nil
1039	}
