1041	// semanticSchemaMinorSkewWarning implements ADR 0001 rule 3: a newer minor
1042	// within the supported major is accepted, but the reader must WARN, because the
1043	// producer may have emitted additive facts this build does not know how to
1044	// ingest. Accepting silently is not compliance — the whole point of the warning
1045	// is that the resulting index is quietly less complete than the snapshot.
1046	//
1047	// This is the single implementation of that rule, applied at every place a
1048	// schema_version crosses into this build alongside validateSemanticSchema:
1049	//
1050	//  1. runSemanticIndex — a live `entire graph snapshot` header, recorded as an
1051	//     index warning on the persisted manifest;
1052	//  2. semanticStaleReport — the "provider" freshness axis reported by brain
1053	//     doctor/status and every semantic read command, degraded rather than ok;
1054	//  3. validateImportedBundle — an imported bundle manifest, warning appended to
1055	//     the semantic source that is then persisted.
1056	//
1057	// It returns nil for an unparseable or non-supported-major version:
1058	// validateSemanticSchema is the sole authority on rejecting those outright, and
1059	// each call site runs it first.
1060	func semanticSchemaMinorSkewWarning(version string) *semanticWarning {
1061		major, minor, err := parseSemanticSchemaVersion(version)
1062		if err != nil {
1063			return nil
1064		}
1065		knownMajor, knownMinor, err := parseSemanticSchemaVersion(semanticSchemaVersion)
1066		if err != nil || strconv.Itoa(major) != semanticSupportedMajor || minor <= knownMinor || major != knownMajor {
1067			return nil
1068		}
1069		return &semanticWarning{
1070			Code:     "provider_schema_newer_minor",
1071			Severity: "warning",
1072			Effect:   "additive semantic facts introduced after " + semanticSchemaVersion + " may not have been ingested",
1073			// Kept under statusCauseWidth: this Detail is rendered inside the
1074			// one-line status cause, and the longer wording was cut mid-word
1075			// ("...so the snapshot is usabl") in the short report.
1076			Detail: fmt.Sprintf(
1077				"provider schema_version %q is newer than this build's %s; minors are additive, so the snapshot is usable -- upgrade to ingest everything",
1078				version, semanticSchemaVersion),
1079		}

