func semanticRecordMaxBytes() int {
	if v := os.Getenv("ENTIRE_BRAIN_MAX_RECORD_BYTES"); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 {
			return n
		}
	}
	return semanticMaxRecordBytes
}

