9	// TestValidateSemanticSchemaFollowsTheTolerantReaderContract pins ADR 0001's
10	// tolerant-reader rules: accept any supported-major minor (including an
11	// additive patch component), refuse an unknown major, and refuse a version
12	// whose major/minor components are not well formed.
13	func TestValidateSemanticSchemaFollowsTheTolerantReaderContract(t *testing.T) {
14		t.Parallel()
15		for _, tc := range []struct {
16			version string
17			wantErr bool
18		}{
19			{version: "1.0"},
20			{version: "1.1"},
21			{version: "1.2"},
22			{version: "1.17"},
23			{version: "1.2.3"},
24			{version: "", wantErr: true},
25			{version: "1", wantErr: true},
26			{version: "2.0", wantErr: true},
27			{version: "0.9", wantErr: true},
28			// A minor that is not a number is not an additive minor: the contract
29			// says major.minor, and silently accepting anything after the dot means
30			// a malformed header rides straight into the store.
31			{version: "1.abc", wantErr: true},
32			{version: "1.", wantErr: true},
33			{version: "x.1", wantErr: true},
34		} {
35			err := validateSemanticSchema(tc.version)
36			if tc.wantErr && err == nil {
37				t.Fatalf("validateSemanticSchema(%q) = nil, want an error", tc.version)
38			}
39			if !tc.wantErr && err != nil {
40				t.Fatalf("validateSemanticSchema(%q) = %v, want nil", tc.version, err)
41			}
42		}
43	}
