4034			// The builder reports source failures per member and still serves healthy
4035			// repositories. Bind that degraded state too, so recovery invalidates it.
4036			member := memberSource{Repo: repo, Manifest: source, Unavailable: err != nil}
4037			// Graph can be rebuilt independently of Brain. Bind derived cross-repo
4038			// edges to the current provider entry, including its missing state.
4039			if repo.LocalPathHint != "" {
