4045				}
4046			}
4047			members = append(members, member)
4048		}
4049		sort.Slice(members, func(i, j int) bool { return members[i].Repo.RepoKey < members[j].Repo.RepoKey })
4050		data, err := json.Marshal(members)
4051		if err != nil {
4052			return "", err
4053		}
